345	
346	  // Optional. If set to true, the user will be deleted even if they have associated data.
347	  bool force = 2 [(google.api.field_behavior) = OPTIONAL];
348	}
349	
350	// User statistics messages
351	message UserStats {
352	  option (google.api.resource) = {
353	    type: "memos.api.v1/UserStats"
354	    pattern: "users/{user}"
355	    singular: "userStats"
356	    plural: "userStats"
357	  };
358	
359	  // The resource name of the user whose stats these are.
360	  // Format: users/{user}
361	  string name = 1 [(google.api.field_behavior) = IDENTIFIER];
362	
363	  reserved 2;
364	  reserved "memo_display_timestamps";
365	
366	  // The stats of memo types.
367	  MemoTypeStats memo_type_stats = 3;
368	
369	  // The count of tags.
370	  map<string, int32> tag_count = 4;
371	
372	  // The creation timestamps of the user's memos.
373	  repeated google.protobuf.Timestamp memo_created_timestamps = 7;
374	
375	  // The latest update timestamps of the user's memos (one per memo,
376	  // mirrors memo_created_timestamps). Used by the activity heatmap when
377	  // the client's view is set to update_time basis.
378	  repeated google.protobuf.Timestamp memo_updated_timestamps = 8;
379	
380	  // The pinned memos of the user.
381	  repeated string pinned_memos = 5;
